// fight_check.rs:1196~1348
fn check_favorable_engage_formation(version, player, data, target_enemy, engage_range) -> bool {

  // [1203] 내 챔프 얻기
  team = player[0x930];                       // 2 이상이면 panic
  pos  = player[0x9c0] as usize;              // Position::as_index()
  slots = data[0x0][0x1e0] + team*40;         // &[Option<&Entity>; 5]
  champ = slots[pos].unwrap();                // null 이면 unwrap_failed panic
  enemy_team = 1 - team;                      // [1204]

  // [1208~1209] 미니언 라인 위험 게이트
  tx = target_enemy[0x660]; ty = target_enemy[0x668];
  k  = data[0x8][0x8][0x12f8] * 2;
  if enemy_minion_line_action_danger_damage_at(version, data, champ, tx, ty, k, true, false) != 0 {
      return false;                           // 적 미니언 라인 피해가 예상되면 진형 계산 없이 즉시 불리
  }

  // [1214~1216] 적 본진(분수) 중심
  (elx, ely, erx, ery) = MapDef::fountain(map, enemy_team);   // map_def.rs:234~235, MapDef+0x6d70 + enemy_team*32
  enemy_base_x = (erx + elx) / 2;             // [1215] (IR 은 (erx+elx) >> 1)
  enemy_base_y = (ery + ely) / 2;             // [1216]

  // [1219~1223] 적의 '후퇴 벡터' = 적 -> 적 본진 (i128 연산)
  retreat_dx = enemy_base_x - tx;             // [1219]
  retreat_dy = enemy_base_y - ty;             // [1220]
  retreat_len_sq = retreat_dx^2 + retreat_dy^2;   // [1221]
  if retreat_len_sq < 1 { return true; }      // [1223] 적이 이미 본진 중심 = 무조건 유리

  front_allies = 0; flank_allies = 0; rear_allies = 0;   // [1229~1231]

  // [1294]/[1334] 공통항 (LLVM 이 루프 밖으로 끌어냄)
  enemy_to_base_sq = |tx-enemy_base_x|^2 + |ty-enemy_base_y|^2;
  max_engage_dist  = engage_range + 100000;   // [1246]

  for ap in 0..5 {                            // [1233] 내 팀 슬롯 5칸 전수
    ally = slots[ap]; if ally == null { continue; }        // [1234]
    if ally[0x5c0] == champ[0x5c0] { continue; }           // [1235] 자기 자신 제외
    if ally[0x670]*100 / ally[0x628] < 40 { continue; }    // [1240] HP 40% 미만 아군은 셈에서 뺀다

    // [1245~1247] 교전권 밖 아군 제외
    ally_to_enemy_dist_sq = |ally.x-tx|^2 + |ally.y-ty|^2; // Entity::distance_sq
    if ally_to_enemy_dist_sq > max_engage_dist^2 { continue; }

    // [1252~1254] 아군 -> 적 벡터 (i128)
    ally_dx = tx - ally.x; ally_dy = ty - ally.y;
    ally_len_sq = ally_dx^2 + ally_dy^2;
    if ally_len_sq < 1 { front_allies += 1; continue; }     // [1256~1258] 적과 겹쳐 있으면 전면으로 셈

    dot   = ally_dx*retreat_dx + ally_dy*retreat_dy;        // [1264]
    cross = ally_dx*retreat_dy - ally_dy*retreat_dx;        // [1267]
    len_product_sq = ally_len_sq * retreat_len_sq;          // [1270]
    dot_sq   = dot*dot;                                     // [1278]
    cross_sq = cross*cross;                                 // [1279]

    // 아래 3개는 sqrt 없이 제곱 비교로 각도를 판정한다
    is_front             = dot > 0 && dot_sq*4   > len_product_sq;      // [1280] cos^2 > 1/4 -> 적 후퇴방향과 60도 이내(아군이 적의 퇴로 쪽에 있음)
    is_rear_direction    = dot < 0 && dot_sq*100 > len_product_sq*9;    // [1283] cos < -0.3 -> 아군이 적 본진의 반대편
    is_significant_flank = cross_sq*100 > len_product_sq*9;             // [1286] |sin| > 0.3 -> 측면각 약 17.5도 초과

    if is_front {                                          // [1288]
        front_allies += 1;                                 // [1289]
    } else if is_rear_direction {                          // [1290]
        to_base_dist_sq = |ally.x-enemy_base_x|^2 + |ally.y-enemy_base_y|^2;   // [1293]
        if to_base_dist_sq < enemy_to_base_sq { rear_allies  += 1; }  // [1296,1298] 아군이 적보다 적 본진에 더 가깝다 = 진짜 퇴로 차단
        else                                  { flank_allies += 1; }  // [1300]
    } else if is_significant_flank {                        // [1302]
        flank_allies += 1;                                 // [1304]
    } else {
        front_allies += 1;                                 // [1307]
    }
  }

  // ---- 진형 판정 ----
  if rear_allies > 0 { return true; }                      // [1316] 퇴로 차단 아군이 1명이라도 있으면 유리
  if flank_allies > 1 || (flank_allies > 0 && front_allies > 0) { return true; }  // [1321] 협공 성립
  if front_allies <= 1 { return false; }                   // [1331] 전면 아군이 2명 미만이면 불리

  // [1334~1340] 전면 2명 이상뿐일 때의 마지막 조건: 위치 우위
  champ_to_base_sq = |champ.x-enemy_base_x|^2 + |champ.y-enemy_base_y|^2;   // [1335]
  return champ_to_base_sq * 5 <= enemy_to_base_sq * 6;     // [1340] 내가 적 본진에서 적보다 크게 멀지 않을 것(실거리비 <= 약 1.095)
}

// 가드(재현 대상 아님): panic_bounds_check(1203), Option::unwrap_failed(1203), panic_const_div_by_zero(1240)
// 반환 경로 요약: false = [1208 미니언위험] / [1331 front<=1] / [1340 거리비 불통과]
//                 true  = [1223 퇴화] / [1316 rear>0] / [1321 협공] / [1340 거리비 통과]
